import{_ as r,a0 as e,w as a,s as u,ao as p,I as l,x as n,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"區塊鏈 2.0：房地產區塊鏈（四） | LCTT x X-CMD","titleTemplate":false,"description":"區塊鏈 2.0：房地產區塊鏈（四） | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"區塊鏈 2.0：房地產區塊鏈（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"區塊鏈 2.0：房地產區塊鏈（四） | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190319 Blockchain 2.0- Blockchain In Real Estate -Part 4","title":"區塊鏈 2.0：房地產區塊鏈（四）","tag":"201905","desc":""},"relativePath":"201905/20190319 Blockchain 2.0- Blockchain In Real Estate -Part 4.md","filePath":"[post].md"}'),f={name:"201905/20190319 Blockchain 2.0- Blockchain In Real Estate -Part 4.md"};function w(d,t,m,T,k,b){const i=e("Link");return a(),u("div",null,[t[40]||(t[40]=p('<h1 id="區塊鏈-2-0-房地產區塊鏈-四" tabindex="-1">區塊鏈 2.0：房地產區塊鏈（四） <a class="header-anchor" href="#區塊鏈-2-0-房地產區塊鏈-四" aria-label="Permalink to “區塊鏈 2.0：房地產區塊鏈（四）”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/03/Blockchain-In-Real-Estate-720x340.png" alt=""></p><h3 id="區塊鏈-2-0-更-智能的房地產" tabindex="-1">區塊鏈 2.0：“更”智能的房地產 <a class="header-anchor" href="#區塊鏈-2-0-更-智能的房地產" aria-label="Permalink to “區塊鏈 2.0：“更”智能的房地產”">​</a></h3>',3)),l("p",null,[t[1]||(t[1]=n("在本系列的",-1)),s(i,{href:"https://linux.cn/article-10689-1.html"},{default:o(()=>[...t[0]||(t[0]=[n("上一篇文章",-1)])]),_:1}),t[2]||(t[2]=n("中我們探討了區塊鏈的特徵，這些區塊鏈將使機構能夠將",-1)),t[3]||(t[3]=l("strong",null,"傳統銀行",-1)),t[4]||(t[4]=n("和",-1)),t[5]||(t[5]=l("strong",null,"融資系統",-1)),t[6]||(t[6]=n("轉換和交織在一起。這部分將探討",-1)),t[7]||(t[7]=l("strong",null,"房地產區塊鏈",-1)),t[8]||(t[8]=n("。房地產業正在走向革命。它是人類已知的交易最活躍、最重要的資產類別之一。然而，由於充滿了監管障礙和欺詐、欺騙的無數可能性，它也是最難參與交易的之一。利用適當的共識算法的區塊鏈的分佈式分類賬本功能被吹捧為這個行業的前進方向，而這個行業傳統上被認為其面對變革是保守的。",-1))]),t[41]||(t[41]=l("p",null,"就其無數的業務而言，房地產一直是一個非常保守的行業。這似乎也是理所當然的。2008 年金融危機或 20 世紀上半葉的大蕭條等重大經濟危機成功摧毀了該行業及其參與者。然而，與大多數具有經濟價值的產品一樣，房地產行業具有彈性，而這種彈性則源於其保守性。",-1)),t[42]||(t[42]=l("p",null,"全球房地產市場由價值 228 萬億 [^1] 美元的資產類別組成，出入不大。其他投資資產，如股票、債券和股票合計價值僅為 170 萬億美元。顯然，在這樣一個行業中實施的交易在很大程度上都是精心策劃和執行的。很多時候，房地產也因許多欺詐事件而臭名昭著，並且隨之而來的是毀滅性的損失。由於其運營非常保守，該行業也難以駕馭。它受到了法律的嚴格監管，創造了一個交織在一起的細微差別網絡，這對於普通人來説太難以完全理解，使得大多數人無法進入和參與。如果你曾參與過這樣的交易，那麼你就會知道紙質文件的重要性和長期性。",-1)),l("p",null,[t[11]||(t[11]=n("從一個微不足道的開始，雖然是一個重要的例子，以顯示當前的記錄管理實踐在房地產行業有多糟糕，考慮一下",-1)),s(i,{href:"https://www.forbes.com/sites/jordanlulich/2018/06/21/what-is-title-insurance-and-why-its-important/#1472022b12bb"},{default:o(()=>[...t[9]||(t[9]=[n("產權保險業務",-1)])]),_:1}),t[12]||(t[12]=n(" [^3]。產權保險用於對沖土地所有權和所有權記錄不可接受且從而無法執行的可能性。諸如此類的保險產品也稱為賠償保險。在許多情況下，法律要求財產擁有產權保險，特別是在處理多年來多次易手的財產時。抵押貸款公司在支持房地產交易時也可能堅持同樣的要求。事實上，這種產品自 19 世紀 50 年代就已存在，並且僅在美國每年至少有 1.5 萬億美元的商業價值這一事實證明了一開始的説法。在這種情況下，這些記錄的維護方式必須進行改革，區塊鏈提供了一個可持續解決方案。根據",-1)),s(i,{href:"https://www.cbinsights.com/research/blockchain-real-estate-disruption/#financing"},{default:o(()=>[...t[10]||(t[10]=[n("美國土地產權協會",-1)])]),_:1}),t[13]||(t[13]=n("，平均每個案例的欺詐平均約為 10 萬美元，並且涉及交易的所有產權中有 25％ 的文件存在問題。區塊鏈允許設置一個不可變的永久資料庫，該資料庫將跟蹤資產本身，記錄已經進入的每個交易或投資。這樣的分類帳本系統將使包括一次性購房者在內的房地產行業的每個人的生活更加輕鬆，並使諸如產權保險等金融產品基本上無關緊要。將諸如房地產之類的實物資產轉換為這樣的數字資產是非常規的，並且目前僅在理論上存在。然而，這種變化迫在眉睫，而不是遲到 [^5]。",-1))]),l("p",null,[t[16]||(t[16]=n("區塊鏈在房地產中影響最大的領域如上所述，在維護透明和安全的產權管理系統方面。基於區塊鏈的財產記錄可以包含有關財產、其所在地、所有權歷史以及相關的公共記錄的",-1)),s(i,{href:"https://www2.deloitte.com/us/en/pages/financial-services/articles/blockchain-in-commercial-real-estate.html"},{default:o(()=>[...t[14]||(t[14]=[n("信息",-1)])]),_:1}),t[17]||(t[17]=n("。這將允許房地產交易快速完成，並且無需第三方監控和監督。房地產評估和税收計算等任務成為有形的、客觀的參數問題，而不是主觀測量和猜測，因為可靠的歷史數據是可公開驗證的。",-1)),s(i,{href:"https://www.ubitquity.io/"},{default:o(()=>[...t[15]||(t[15]=[n("UBITQUITY",-1)])]),_:1}),t[18]||(t[18]=n(" 就是這樣一個平台，為企業客户提供定製的基於區塊鏈的解決方案。該平台允許客户跟蹤所有房產細節、付款記錄、抵押記錄，甚至允許運行智能合約，自動處理税收和租賃。",-1))]),l("p",null,[t[20]||(t[20]=n("這為我們帶來了房地產區塊鏈的第二大機遇和用例。由於該行業受到眾多第三方的高度監管，除了參與交易的交易對手外，盡職調查和財務評估可能非常耗時。這些流程主要通過離線渠道進行，文書工作需要在最終評估報告出來之前進行數天。對於公司房地產交易尤其如此，這構成了顧問所收取的總計費時間的大部分。如果交易由抵押背書，則這些過程的重複是不可避免的。一旦與所涉及的人員和機構的數字身份相結合，就可以完全避免當前的低效率，並且可以在幾秒鐘內完成交易。租户、投資者、相關機構、顧問等可以單獨驗證數據並達成一致的共識，從而驗證永久性的財產記錄 [^8]。這提高了驗證流程的準確性。房地產巨頭 RE/MAX 最近宣佈與服務提供商 XYO Network Partners 合作，",-1)),s(i,{href:"https://www.businesswire.com/news/home/20181012005068/en/XYO-Network-Partners-REMAX-M%C3%A9xico-Bring-Blockchain"},{default:o(()=>[...t[19]||(t[19]=[n("建立墨西哥房上市地產國家資料庫",-1)])]),_:1}),t[21]||(t[21]=n("。他們希望有朝一日能夠創建世界上最大的（截至目前）去中心化房地產登記中心之一。",-1))]),l("p",null,[t[23]||(t[23]=n("然而，區塊鏈可以帶來的另一個重要且可以説是非常民主的變化是投資房地產。與其他投資資產類別不同，即使是小型家庭投資者也可能參與其中，房地產通常需要大量的手工付款才能參與。諸如 ATLANT 和 BitOfProperty 之類的公司將房產的賬面價值代幣化，並將其轉換為加密貨幣的等價物。這些代幣隨後在交易所出售，類似於股票和股票的交易方式。",-1)),s(i,{href:"https://www.cbinsights.com/research/blockchain-real-estate-disruption/#financing"},{default:o(()=>[...t[22]||(t[22]=[n("房地產後續產生的任何現金流都會根據其在財產中的“份額”記入貸方或借記給代幣所有者",-1)])]),_:1}),t[24]||(t[24]=n("。",-1))]),t[43]||(t[43]=l("p",null,"然而，儘管如此，區塊鏈技術仍處於房地產領域的早期採用階段，目前的法規還沒有明確定義它。諸如分佈式應用程序、分佈式匿名組織（DAO）、智能合約等概念在許多國家的法律領域是聞所未聞的。一旦所有利益相關者充分接受了區塊鏈複雜性的良好教育，就會徹底改革現有的法規和指導方針，這是最務實的前進方式。 同樣，這將是一個緩慢而漸進的變化，但是它是一個急需的變化。本系列的下一篇文章將介紹 “智能合約”，例如由 UBITQUITY 和 XYO 等公司實施的那些是如何在區塊鏈中創建和執行的。",-1)),t[44]||(t[44]=l("p",null,"[^1]: HSBC, “Global Real Estate,” no. April, 2008 [^3]: D. B. Burke, Law of title insurance. Aspen Law & Business, 2000. [^5]: M. Swan, O’Reilly – Blockchain. Blueprint for a New Economy – 2015. [^8]: Deloite, “Blockchain in commercial real estate The future is here ! Table of contents.”",-1)),t[45]||(t[45]=l("hr",null,null,-1)),l("p",null,[t[26]||(t[26]=n("via: ",-1)),s(i,{href:"https://www.ostechnix.com/blockchain-2-0-blockchain-in-real-estate/"},{default:o(()=>[...t[25]||(t[25]=[n("https://www.ostechnix.com/blockchain-2-0-blockchain-in-real-estate/",-1)])]),_:1})]),l("p",null,[t[31]||(t[31]=n("作者：",-1)),s(i,{href:"https://www.ostechnix.com/author/editor/"},{default:o(()=>[...t[27]||(t[27]=[n("ostechnix",-1)])]),_:1}),t[32]||(t[32]=n(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[28]||(t[28]=[n("lujun9972",-1)])]),_:1}),t[33]||(t[33]=n(" 譯者：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[29]||(t[29]=[n("wxy",-1)])]),_:1}),t[34]||(t[34]=n(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[30]||(t[30]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[37]||(t[37]=n("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[35]||(t[35]=[n("LCTT",-1)])]),_:1}),t[38]||(t[38]=n(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...t[36]||(t[36]=[n("Linux中國",-1)])]),_:1}),t[39]||(t[39]=n(" 榮譽推出",-1))])])}const C=r(f,[["render",w]]);export{g as __pageData,C as default};
